query($id:String!){
  target(ensemblId:$id){
    id approvedSymbol
    tractability{ label value modality }
    chemicalProbes{ id isHighQuality }
    drugAndClinicalCandidates{
      count
      rows{
        maxClinicalStage
        drug{ id name drugType maximumClinicalStage }
        diseases{ disease{ id name } }
      }
    }
  }
}
